     6→using System.Collections.Generic;
     7→using System.Diagnostics.CodeAnalysis;
     8→using System.Runtime.CompilerServices;
     9→using System.Runtime.InteropServices;
    10→using System.Runtime.Intrinsics;
    11→using System.Threading.Tasks;
    12→using Nethermind.Core;
    13→using Nethermind.Core.Collections;
    14→using Nethermind.Core.Crypto;
    15→using Nethermind.Core.Extensions;
    16→using Nethermind.Core.Threading;
    17→using Nethermind.Evm.Tracing.State;
    18→using Nethermind.Int256;
    19→using Nethermind.Logging;
    20→using Nethermind.Serialization.Rlp;
    21→using Nethermind.Trie;
    22→using Nethermind.Trie.Pruning;
    23→
    24→namespace Nethermind.State;
    25→
    26→using Nethermind.Core.Cpu;
    27→
    28→/// <summary>
    29→/// Manages persistent storage allowing for snapshotting and restoring
    30→/// Persists data to ITrieStore
    31→/// </summary>
    32→internal sealed class PersistentStorageProvider : PartialStorageProviderBase
    33→{
    34→    private readonly ITrieStore _trieStore;
    35→    private readonly StateProvider _stateProvider;
    36→    private readonly ILogManager? _logManager;
    37→    internal readonly IStorageTreeFactory _storageTreeFactory;
    38→    private readonly Dictionary<AddressAsKey, PerContractState> _storages = new(4_096);
    39→    private readonly Dictionary<AddressAsKey, bool> _toUpdateRoots = new();
    40→
    41→    /// <summary>
    42→    /// EIP-1283
    43→    /// </summary>
    44→    private readonly Dictionary<StorageCell, byte[]> _originalValues = new();
    45→
    46→    private readonly HashSet<StorageCell> _committedThisRound = new();
    47→    private readonly ConcurrentDictionary<StorageCell, byte[]>? _preBlockCache;
    48→
    49→    /// <summary>
    50→    /// Manages persistent storage allowing for snapshotting and restoring
    51→    /// Persists data to ITrieStore
    52→    /// </summary>
    53→    public PersistentStorageProvider(ITrieStore trieStore,
    54→        StateProvider stateProvider,
    55→        ILogManager logManager,
    56→        IStorageTreeFactory? storageTreeFactory,
    57→        ConcurrentDictionary<StorageCell, byte[]>? preBlockCache,
    58→        bool populatePreBlockCache) : base(logManager)
    59→    {
    60→        _trieStore = trieStore ?? throw new ArgumentNullException(nameof(trieStore));
    61→        _stateProvider = stateProvider ?? throw new ArgumentNullException(nameof(stateProvider));
    62→        _logManager = logManager ?? throw new ArgumentNullException(nameof(logManager));
    63→        _storageTreeFactory = storageTreeFactory ?? new StorageTreeFactory();
    64→        _preBlockCache = preBlockCache;
    65→        _populatePreBlockCache = populatePreBlockCache;
    66→    }
    67→
    68→    public Hash256 StateRoot { get; set; } = null!;
    69→    private readonly bool _populatePreBlockCache;
    70→
    71→    /// <summary>
    72→    /// Reset the storage state
    73→    /// </summary>
    74→    public override void Reset(bool resetBlockChanges = true)
    75→    {
    76→        base.Reset();
    77→        _originalValues.Clear();
    78→        _committedThisRound.Clear();
    79→        if (resetBlockChanges)
    80→        {
    81→            _storages.Clear();
    82→            _toUpdateRoots.Clear();
    83→        }
    84→    }
    85→
    86→    /// <summary>
    87→    /// Get the current value at the specified location
    88→    /// </summary>
    89→    /// <param name="storageCell">Storage location</param>
    90→    /// <returns>Value at location</returns>
    91→    protected override ReadOnlySpan<byte> GetCurrentValue(in StorageCell storageCell) =>
    92→        TryGetCachedValue(storageCell, out byte[]? bytes) ? bytes! : LoadFromTree(storageCell);
    93→
    94→    /// <summary>
    95→    /// Return the original persistent storage value from the storage cell
    96→    /// </summary>
    97→    /// <param name="storageCell"></param>
    98→    /// <returns></returns>
    99→    public byte[] GetOriginal(in StorageCell storageCell)
   100→    {
   101→        if (!_originalValues.TryGetValue(storageCell, out var value))
   102→        {
   103→            throw new InvalidOperationException("Get original should only be called after get within the same caching round");
   104→        }
   105→
   106→        if (_transactionChangesSnapshots.TryPeek(out int snapshot))
   107→        {
   108→            if (_intraBlockCache.TryGetValue(storageCell, out StackList<int> stack))
   109→            {
   110→                if (stack.TryGetSearchedItem(snapshot, out int lastChangeIndexBeforeOriginalSnapshot))
   111→                {
   112→                    return _changes[lastChangeIndexBeforeOriginalSnapshot].Value;
   113→                }
   114→            }
   115→        }
   116→
   117→        return value;
   118→    }
   119→
   120→    private HashSet<AddressAsKey>? _tempToUpdateRoots;
   121→    /// <summary>
   122→    /// Called by Commit
   123→    /// Used for persistent storage specific logic
   124→    /// </summary>
   125→    /// <param name="tracer">Storage tracer</param>
   126→    protected override void CommitCore(IStorageTracer tracer)
   127→    {
   128→        if (_logger.IsTrace) _logger.Trace("Committing storage changes");
   129→
   130→        int currentPosition = _changes.Count - 1;
   131→        if (currentPosition < 0)
   132→        {
   133→            return;
   134→        }
   135→        if (_changes[currentPosition].IsNull)
   136→        {
   137→            throw new InvalidOperationException($"Change at current position {currentPosition} was null when committing {nameof(PartialStorageProviderBase)}");
   138→        }
   139→
   140→        HashSet<AddressAsKey> toUpdateRoots = (_tempToUpdateRoots ??= new());
   141→
   142→        bool isTracing = tracer.IsTracingStorage;
   143→        Dictionary<StorageCell, ChangeTrace>? trace = null;
   144→        if (isTracing)
   145→        {
   146→            trace = new Dictionary<StorageCell, ChangeTrace>();
   147→        }
   148→
   149→        for (int i = 0; i <= currentPosition; i++)
   150→        {
   151→            Change change = _changes[currentPosition - i];
   152→            if (!isTracing && change!.ChangeType == ChangeType.JustCache)
   153→            {
   154→                continue;
   155→            }
   156→
   157→            if (_committedThisRound.Contains(change!.StorageCell))
   158→            {
   159→                if (isTracing && change.ChangeType == ChangeType.JustCache)
   160→                {
   161→                    trace![change.StorageCell] = new ChangeTrace(change.Value, trace[change.StorageCell].After);
   162→                }
   163→
   164→                continue;
   165→            }
   166→
   167→            if (isTracing && change.ChangeType == ChangeType.JustCache)
   168→            {
   169→                tracer!.ReportStorageRead(change.StorageCell);
   170→            }
   171→
   172→            _committedThisRound.Add(change.StorageCell);
   173→
   174→            if (change.ChangeType == ChangeType.Destroy)
   175→            {
   176→                continue;
   177→            }
   178→
   179→            int forAssertion = _intraBlockCache[change.StorageCell].Pop();
   180→            if (forAssertion != currentPosition - i)
   181→            {
   182→                throw new InvalidOperationException($"Expected checked value {forAssertion} to be equal to {currentPosition} - {i}");
   183→            }
   184→
   185→            if (change.ChangeType == ChangeType.Update)
   186→            {
   187→                if (_logger.IsTrace)
   188→                {
   189→                    _logger.Trace($"  Update {change.StorageCell.Address}_{change.StorageCell.Index} V = {change.Value.ToHexString(true)}");
   190→                }
   191→
   192→                if (_originalValues.TryGetValue(change.StorageCell, out byte[] initialValue) &&
   193→                    initialValue.AsSpan().SequenceEqual(change.Value))
   194→                {
   195→                    // no need to update the tree if the value is the same
   196→                }
   197→                else
   198→                {
   199→                    toUpdateRoots.Add(change.StorageCell.Address);
   200→
   201→                    GetOrCreateStorage(change.StorageCell.Address)
   202→                        .SaveChange(change.StorageCell, change.Value);
   203→                }
   204→
   205→                if (isTracing)
   206→                {
   207→                    trace![change.StorageCell] = new ChangeTrace(change.Value);
   208→                }
   209→            }
   210→        }
   211→
   212→        foreach (AddressAsKey address in toUpdateRoots)
   213→        {
   214→            // since the accounts could be empty accounts that are removing (EIP-158)
   215→            if (_stateProvider.AccountExists(address))
   216→            {
   217→                _toUpdateRoots[address] = true;
   218→                // Add storage tree, will accessed later, which may be in parallel
   219→                // As we can't add a new storage tries in parallel to the _storages Dict do it here
   220→                GetOrCreateStorage(address).EnsureStorageTree();
   221→            }
   222→            else
   223→            {
   224→                _toUpdateRoots.Remove(address);
   225→                _storages.Remove(address);
   226→            }
   227→        }
   228→        toUpdateRoots.Clear();
   229→
   230→        base.CommitCore(tracer);
   231→        _originalValues.Clear();
   232→        _committedThisRound.Clear();
   233→
   234→        if (isTracing)
   235→        {
   236→            ReportChanges(tracer!, trace!);
   237→        }
   238→    }
   239→
   240→    protected override void CommitStorageRoots()
   241→    {
   242→        if (_toUpdateRoots.Count == 0)
   243→        {
   244→            return;
   245→        }
   246→
   247→        // Is overhead of parallel foreach worth it?
   248→        if (_toUpdateRoots.Count < 3)
   249→        {
   250→            UpdateRootHashesSingleThread();
   251→        }
   252→        else
   253→        {
   254→            UpdateRootHashesMultiThread();
   255→        }
   256→
   257→        _toUpdateRoots.Clear();
   258→
   259→        void UpdateRootHashesSingleThread()
   260→        {
   261→            foreach (KeyValuePair<AddressAsKey, PerContractState> kvp in _storages)
   262→            {
   263→                if (!_toUpdateRoots.TryGetValue(kvp.Key, out bool hasChanges) || !hasChanges)
   264→                {
   265→                    // Wasn't updated don't recalculate
   266→                    continue;
   267→                }
   268→
   269→                PerContractState contractState = kvp.Value;
   270→                (int writes, int skipped) = contractState.ProcessStorageChanges();
   271→                ReportMetrics(writes, skipped);
   272→                if (writes > 0)
   273→                {
   274→                    _stateProvider.UpdateStorageRoot(address: kvp.Key, contractState.RootHash);
   275→                }
   276→            }
   277→        }
   278→
   279→        void UpdateRootHashesMultiThread()
   280→        {
   281→            // We can recalculate the roots in parallel as they are all independent tries
   282→            using var storages = _storages.ToPooledList();
   283→            ParallelUnbalancedWork.For(
   284→                0,
   285→                storages.Count,
   286→                RuntimeInformation.ParallelOptionsPhysicalCoresUpTo16,
   287→                (storages, toUpdateRoots: _toUpdateRoots, writes: 0, skips: 0),
   288→                static (i, state) =>
   289→                {
   290→                    ref var kvp = ref state.storages.GetRef(i);
   291→                    if (!state.toUpdateRoots.TryGetValue(kvp.Key, out bool hasChanges) || !hasChanges)
   292→                    {
   293→                        // Wasn't updated don't recalculate
   294→                        return state;
   295→                    }
   296→
   297→                    (int writes, int skipped) = kvp.Value.ProcessStorageChanges();
   298→                    if (writes == 0)
   299→                    {
   300→                        // Mark as no changes; we set as false rather than removing so
   301→                        // as not to modify the non-concurrent collection without synchronization
   302→                        state.toUpdateRoots[kvp.Key] = false;
   303→                    }
   304→                    else
   305→                    {
   306→                        state.writes += writes;
   307→                    }
   308→
   309→                    state.skips += skipped;
   310→
   311→                    return state;
   312→                },
   313→                (state) => ReportMetrics(state.writes, state.skips));
   314→
   315→            // Update the storage roots in the main thread not in parallel,
   316→            // as can't update the StateTrie in parallel.
   317→            foreach (ref var kvp in storages.AsSpan())
   318→            {
   319→                if (!_toUpdateRoots.TryGetValue(kvp.Key, out bool hasChanges) || !hasChanges)
   320→                {
   321→                    continue;
   322→                }
   323→
   324→                // Update the storage root for the Account
   325→                _stateProvider.UpdateStorageRoot(address: kvp.Key, kvp.Value.RootHash);
   326→            }
   327→        }
   328→
   329→        static void ReportMetrics(int writes, int skipped)
   330→        {
   331→            if (skipped > 0)
   332→            {
   333→                Db.Metrics.IncrementStorageSkippedWrites(skipped);
   334→            }
   335→            if (writes > 0)
   336→            {
   337→                Db.Metrics.IncrementStorageTreeWrites(writes);
   338→            }
   339→        }
   340→    }
   341→
   342→    /// <summary>
   343→    /// Commit persistent storage trees
   344→    /// </summary>
   345→    /// <param name="blockNumber">Current block number</param>
   346→    public void CommitTrees(IBlockCommitter blockCommitter)
   347→    {
   348→        // Note: These all runs in about 0.4ms. So the little overhead like attempting to sort the tasks
   349→        // may make it worst. Always check on mainnet.
   350→
   351→        using ArrayPoolList<Task> commitTask = new ArrayPoolList<Task>(_storages.Count);
   352→        foreach (KeyValuePair<AddressAsKey, PerContractState> storage in _storages)
   353→        {
   354→            storage.Value.EnsureStorageTree(); // Cannot be called concurrently
   355→            if (blockCommitter.TryRequestConcurrencyQuota())
   356→            {
   357→                commitTask.Add(Task.Factory.StartNew((ctx) =>
   358→                {
   359→                    PerContractState st = (PerContractState)ctx;
   360→                    st.Commit();
   361→                    blockCommitter.ReturnConcurrencyQuota();
   362→                }, storage.Value));
   363→            }
   364→            else
   365→            {
   366→                storage.Value.Commit();
   367→            }
   368→        }
   369→
   370→        Task.WaitAll(commitTask.AsSpan());
   371→
   372→        _storages.Clear();
   373→    }
   374→
   375→    private PerContractState GetOrCreateStorage(Address address)
   376→    {
   377→        ref PerContractState? value = ref CollectionsMarshal.GetValueRefOrAddDefault(_storages, address, out bool exists);
   378→        if (!exists) value = new PerContractState(address, this);
   379→        return value;
   380→    }
   381→
   382→    public void WarmUp(in StorageCell storageCell, bool isEmpty)
   383→    {
   384→        if (isEmpty)
   385→        {
   386→            if (_preBlockCache is not null)
   387→            {
   388→                _preBlockCache[storageCell] = [];
   389→            }
   390→        }
   391→        else
   392→        {
   393→            LoadFromTree(in storageCell);
   394→        }
   395→    }
   396→
   397→    private ReadOnlySpan<byte> LoadFromTree(in StorageCell storageCell)
   398→    {
   399→        return GetOrCreateStorage(storageCell.Address).LoadFromTree(storageCell);
   400→    }
   401→
   402→    private void PushToRegistryOnly(in StorageCell cell, byte[] value)
   403→    {
   404→        StackList<int> stack = SetupRegistry(cell);
   405→        _originalValues[cell] = value;
   406→        stack.Push(_changes.Count);
   407→        _changes.Add(new Change(in cell, value, ChangeType.JustCache));
   408→    }
   409→
   410→    private static void ReportChanges(IStorageTracer tracer, Dictionary<StorageCell, ChangeTrace> trace)
   411→    {
   412→        foreach ((StorageCell address, ChangeTrace change) in trace)
   413→        {
   414→            byte[] before = change.Before;
   415→            byte[] after = change.After;
   416→
   417→            if (!Bytes.AreEqual(before, after))
   418→            {
   419→                tracer.ReportStorageChange(address, before, after);
   420→            }
   421→        }
   422→    }
   423→
   424→    /// <summary>
   425→    /// Clear all storage at specified address
   426→    /// </summary>
   427→    /// <param name="address">Contract address</param>
   428→    public override void ClearStorage(Address address)
   429→    {
   430→        base.ClearStorage(address);
   431→
   432→        // here it is important to make sure that we will not reuse the same tree when the contract is revived
   433→        // by means of CREATE 2 - notice that the cached trie may carry information about items that were not
   434→        // touched in this block, hence were not zeroed above
   435→        // TODO: how does it work with pruning?
   436→        _toUpdateRoots.Remove(address);
   437→
   438→        PerContractState state = GetOrCreateStorage(address);
   439→        state.Clear();
   440→    }
   441→
   442→    private class StorageTreeFactory : IStorageTreeFactory
   443→    {
   444→        public StorageTree Create(Address address, IScopedTrieStore trieStore, Hash256 storageRoot, Hash256 stateRoot, ILogManager? logManager)
   445→            => new(trieStore, storageRoot, logManager);
   446→    }
   447→
   448→    private sealed class DefaultableDictionary()
   449→    {
   450→        private bool _missingAreDefault;
   451→        private readonly Dictionary<UInt256, ChangeTrace> _dictionary = new(Comparer.Instance);
   452→        public int EstimatedSize => _dictionary.Count;
   453→
   454→        public void ClearAndSetMissingAsDefault()
   455→        {
   456→            _missingAreDefault = true;
   457→            _dictionary.Clear();
   458→        }
   459→
   460→        public ref ChangeTrace GetValueRefOrAddDefault(UInt256 storageCellIndex, out bool exists)
   461→        {
   462→            ref ChangeTrace value = ref CollectionsMarshal.GetValueRefOrAddDefault(_dictionary, storageCellIndex, out exists);
   463→            if (!exists && _missingAreDefault)
   464→            {
   465→                // Where we know the rest of the tree is empty
   466→                // we can say the value was found but is default
   467→                // rather than having to check the database
   468→                value = ChangeTrace.ZeroBytes;
   469→                exists = true;
   470→            }
   471→            return ref value;
   472→        }
   473→
   474→        public ref ChangeTrace GetValueRefOrNullRef(UInt256 storageCellIndex)
   475→            => ref CollectionsMarshal.GetValueRefOrNullRef(_dictionary, storageCellIndex);
   476→
   477→        public ChangeTrace this[UInt256 key]
   478→        {
   479→            set => _dictionary[key] = value;
   480→        }
   481→
   482→        public Dictionary<UInt256, ChangeTrace>.Enumerator GetEnumerator() => _dictionary.GetEnumerator();
   483→
   484→        private sealed class Comparer : IEqualityComparer<UInt256>
   485→        {
   486→            public static Comparer Instance { get; } = new();
   487→
   488→            private Comparer() { }
   489→
   490→            public bool Equals(UInt256 x, UInt256 y)
   491→                => Unsafe.As<UInt256, Vector256<byte>>(ref x) == Unsafe.As<UInt256, Vector256<byte>>(ref y);
   492→
   493→            public int GetHashCode([DisallowNull] UInt256 obj)
   494→                => MemoryMarshal.AsBytes(MemoryMarshal.CreateReadOnlySpan(in obj, 1)).FastHash();
   495→        }
   496→    }
   497→
   498→    private sealed class PerContractState
   499→    {
   500→        private StorageTree? StorageTree;
   501→        private DefaultableDictionary BlockChange = new DefaultableDictionary();
   502→        private bool _wasWritten = false;
   503→        private readonly Func<StorageCell, byte[]> _loadFromTreeStorageFunc;
   504→        private readonly Address _address;
   505→        private readonly PersistentStorageProvider _provider;
   506→
   507→        public PerContractState(Address address,
   508→            PersistentStorageProvider provider)
   509→        {
   510→            _address = address;
   511→            _provider = provider;
   512→            _loadFromTreeStorageFunc = LoadFromTreeStorage;
   513→        }
   514→
   515→        public void EnsureStorageTree()
   516→        {
   517→            if (StorageTree is not null) return;
   518→
   519→            // Note: GetStorageRoot is not concurrent safe! And so do this whole method!
   520→            Account? acc = _provider._stateProvider.GetAccount(_address);
   521→            Hash256 storageRoot = acc?.StorageRoot ?? Keccak.EmptyTreeHash;
   522→            bool isEmpty = storageRoot == Keccak.EmptyTreeHash; // We know all lookups will be empty against this tree
   523→            StorageTree = _provider._storageTreeFactory.Create(_address,
   524→                _provider._trieStore.GetTrieStore(_address),
   525→                storageRoot,
   526→                _provider.StateRoot,
   527→                _provider._logManager);
   528→
   529→            if (isEmpty && !_wasWritten)
   530→            {
   531→                // Slight optimization that skips the tree
   532→                BlockChange.ClearAndSetMissingAsDefault();
   533→            }
   534→        }
   535→
   536→        public Hash256 RootHash
   537→        {
   538→            get
   539→            {
   540→                EnsureStorageTree();
   541→                return StorageTree.RootHash;
   542→            }
   543→        }
   544→
   545→        public void Commit()
   546→        {
   547→            EnsureStorageTree();
   548→            StorageTree.Commit();
   549→        }
   550→
   551→        public void Clear()
   552→        {
   553→            StorageTree = new StorageTree(_provider._trieStore.GetTrieStore(_address), Keccak.EmptyTreeHash, _provider._logManager);
   554→            BlockChange.ClearAndSetMissingAsDefault();
   555→        }
   556→
   557→        public void SaveChange(StorageCell storageCell, byte[] value)
   558→        {
   559→            _wasWritten = true;
   560→            ref ChangeTrace valueChanges = ref BlockChange.GetValueRefOrAddDefault(storageCell.Index, out bool exists);
   561→            if (!exists)
   562→            {
   563→                valueChanges = new ChangeTrace(value);
   564→            }
   565→            else
   566→            {
   567→                valueChanges.After = value;
   568→            }
   569→        }
   570→
   571→        public ReadOnlySpan<byte> LoadFromTree(in StorageCell storageCell)
   572→        {
   573→            ref ChangeTrace valueChange = ref BlockChange.GetValueRefOrAddDefault(storageCell.Index, out bool exists);
   574→            if (!exists)
   575→            {
   576→                byte[] value = !_provider._populatePreBlockCache ?
   577→                    LoadFromTreeReadPreWarmCache(in storageCell) :
   578→                    LoadFromTreePopulatePrewarmCache(in storageCell);
   579→
   580→                valueChange = new(value, value);
   581→            }
   582→            else
   583→            {
   584→                Db.Metrics.IncrementStorageTreeCache();
   585→            }
   586→
   587→            if (!storageCell.IsHash) _provider.PushToRegistryOnly(storageCell, valueChange.After);
   588→            return valueChange.After;
   589→        }
   590→
   591→        private byte[] LoadFromTreeReadPreWarmCache(in StorageCell storageCell)
   592→        {
   593→            if (_provider._preBlockCache?.TryGetValue(storageCell, out byte[] value) ?? false)
   594→            {
   595→                Db.Metrics.IncrementStorageTreeCache();
   596→            }
   597→            else
   598→            {
   599→                value = LoadFromTreeStorage(storageCell);
   600→            }
   601→            return value;
   602→        }
   603→
   604→        private byte[] LoadFromTreePopulatePrewarmCache(in StorageCell storageCell)
   605→        {
   606→            long priorReads = Db.Metrics.ThreadLocalStorageTreeReads;
   607→
   608→            byte[] value = _provider._preBlockCache is not null
   609→                ? _provider._preBlockCache.GetOrAdd(storageCell, _loadFromTreeStorageFunc)
   610→                : LoadFromTreeStorage(storageCell);
   611→
   612→            if (Db.Metrics.ThreadLocalStorageTreeReads == priorReads)
   613→            {
   614→                // Read from Concurrent Cache
   615→                Db.Metrics.IncrementStorageTreeCache();
   616→            }
   617→            return value;
   618→        }
   619→
   620→        private byte[] LoadFromTreeStorage(StorageCell storageCell)
   621→        {
   622→            Db.Metrics.IncrementStorageTreeReads();
   623→
   624→            EnsureStorageTree();
   625→            return !storageCell.IsHash
   626→                ? StorageTree.Get(storageCell.Index)
   627→                : StorageTree.GetArray(storageCell.Hash.Bytes);
   628→        }
   629→
   630→        public (int writes, int skipped) ProcessStorageChanges()
   631→        {
   632→            EnsureStorageTree();
   633→
   634→            int writes = 0;
   635→            int skipped = 0;
   636→            if (BlockChange.EstimatedSize < PatriciaTree.MinEntriesToParallelizeThreshold)
   637→            {
   638→                foreach (var kvp in BlockChange)
   639→                {
   640→                    byte[] after = kvp.Value.After;
   641→                    if (!Bytes.AreEqual(kvp.Value.Before, after) || kvp.Value.IsInitialValue)
   642→                    {
   643→                        BlockChange[kvp.Key] = new(after, after);
   644→                        StorageTree.Set(kvp.Key, after);
   645→                        writes++;
   646→                    }
   647→                    else
   648→                    {
   649→                        skipped++;
   650→                    }
   651→                }
   652→            }
   653→            else
   654→            {
   655→                using ArrayPoolList<PatriciaTree.BulkSetEntry> bulkWrite = new(BlockChange.EstimatedSize);
   656→
   657→                Span<byte> keyBuf = stackalloc byte[32];
   658→                foreach (var kvp in BlockChange)
   659→                {
   660→                    byte[] after = kvp.Value.After;
   661→                    if (!Bytes.AreEqual(kvp.Value.Before, after))
   662→                    {
   663→                        BlockChange[kvp.Key] = new(after, after);
   664→
   665→                        StorageTree.ComputeKeyWithLookup(kvp.Key, keyBuf);
   666→                        bulkWrite.Add(StorageTree.CreateBulkSetEntry(new ValueHash256(keyBuf), after));
   667→
   668→                        writes++;
   669→                    }
   670→                    else
   671→                    {
   672→                        skipped++;
   673→                    }
   674→                }
   675→
   676→                StorageTree.BulkSet(bulkWrite);
   677→            }
   678→
   679→            if (writes > 0)
   680→            {
   681→                StorageTree.UpdateRootHash(canBeParallel: writes > 64);
   682→            }
   683→
   684→            return (writes, skipped);
   685→        }
   686→    }
   687→}
